// 4. AUTHORIZE ORDER (Authorizer or Company)
router.put('/:id/authorize', protect, authorize('company', 'authorizer'), async (req, res) => {
  try {
    const order = await Order.findById(req.params.id);

    if (!order) {
      return res.status(404).json({ message: 'Order not found' });
    }

    // Verify ownership by brand or company id
    const userBrandIds = req.user.brandIds && req.user.brandIds.length > 0 
      ? req.user.brandIds.map(id => id.toString()) 
      : (req.user.brandId ? [req.user.brandId.toString()] : (req.user.role === 'company' ? [req.user._id.toString()] : []));

    const companyId = req.user.companyId || (req.user.role === 'company' ? req.user._id : null);
    
    const isBrandMatch = order.brandId && userBrandIds.includes(order.brandId.toString());
    const isCompanyMatch = order.companyId && companyId && order.companyId.toString() === companyId.toString();
    const isLegacyMatch = order.company && req.user.role === 'company' && order.company.toString() === req.user._id.toString();

    if (!isBrandMatch && !isCompanyMatch && !isLegacyMatch) {
      return res.status(403).json({ message: 'Not authorized for this order' });
    }

    if (order.status !== 'Pending Authorization') {
      return res.status(400).json({ message: 'Order cannot be authorized in its current state' });
    }

    // --- Credit check & deduction ---
    const brand = await Brand.findById(order.brandId);
    if (!brand || !brand.companyId) {
      return res.status(400).json({ message: 'Brand or company not found for this order' });
    }
    const company = await Company.findById(brand.companyId);
    if (!company) {
      return res.status(400).json({ message: 'Company not found' });
    }
    
    const required = order.quantity || 0;

    // ============================================
    // AUTOMATIC PROCESSING (MAP PHYSICAL QRS)
    // ============================================
    const BlankQr = __nccwpck_require__(50294);
    const Product = __nccwpck_require__(67692);
    const ProductCoupon = __nccwpck_require__(13726);
    const totalQty = required;
    const brandName = order.brand;
    
    // Fetch ProductTemplate and copy orderLinks
    const ProductTemplate = __nccwpck_require__(58846);
    let templateOrderLinks = [];
    let templateEducationContent = [];
    if (order.templateId) {
      const tpl = await ProductTemplate.findById(order.templateId).lean();
      if (tpl && tpl.orderLinks) templateOrderLinks = tpl.orderLinks;
      if (tpl && tpl.educationContent) templateEducationContent = tpl.educationContent;
    }

    // Find last sequence number for this brand
    const lastProduct = await Product.findOne({ brand: brandName }).sort({ sequence: -1 });
    let startSeq = lastProduct && lastProduct.sequence ? lastProduct.sequence + 1 : 1;
    const brandDoc = await Brand.findOne({ brandName: brandName });

    // Fetch unassigned physical QRs
    const qrsToUse = await BlankQr.find({ 
        assignedToCompany: company._id,
        isAssigned: false,
        isBlocked: false
    })
    .sort({ serialNumber: 1 })
    .limit(totalQty);

    if (qrsToUse.length < totalQty) {
        return res.status(400).json({ 
            message: `Not enough physical Blank QRs available for this company in database. Requested: ${totalQty}, Found: ${qrsToUse.length}. Please ask Superadmin to assign more stock.` 
        });
    }

    const productsToCreate = [];
    for (let i = 0; i < totalQty; i++) {
      const currentSeq = startSeq + i;
      const qrCode = qrsToUse[i].qrCode;
      
      productsToCreate.push({
        qrCode,
        productName: order.productName,
        skuNumber: order.skuNumber,
        brand: brandName,
        brandId: brandDoc ? brandDoc._id : null,
        batchNo: order.batchNo,
        manufactureDate: order.manufactureDate,
        expiryDate: order.expiryDate,
        productImage: order.productImage,
        mfdOn: (order.mfdOn && order.mfdOn.month && order.mfdOn.year) ? order.mfdOn : undefined,
        bestBefore: (order.bestBefore && order.bestBefore.value) ? order.bestBefore : undefined,
        calculatedExpiryDate: order.calculatedExpiryDate,
        dynamicFields: order.dynamicFields,
        variants: order.variants,
        warranty: (order.warranty && (order.warranty.duration || order.warranty.warrantyType)) ? order.warranty : undefined,
        supplyChain: order.supplyChain || undefined,
        orderLinks: (order.orderLinks && order.orderLinks.length > 0) ? order.orderLinks : templateOrderLinks,
        educationContent: templateEducationContent,
        description: order.description,
        productInfo: order.productInfo,
        quantity: 1,
        qrType: order.qrType || 'product',
        sequence: currentSeq,
        orderId: order._id,
        isActive: true, // Physical QRs are instantly active
        createdBy: req.user._id
      });
    }
    
    const insertedProducts = await Product.insertMany(productsToCreate);
    
    // Map Blank QRs to the created products
    const bulkOps = insertedProducts.map((prod, index) => ({
        updateOne: {
            filter: { _id: qrsToUse[index]._id },
            update: { $set: { isAssigned: true, assignedToProduct: prod._id } }
        }
    }));
    await BlankQr.bulkWrite(bulkOps);

    // Sync company qrCredits cache
    const unassignedForCompanyCount = await BlankQr.countDocuments({
       assignedToCompany: company._id,
       isAssigned: false,
       isBlocked: false
    });
    company.qrCredits = unassignedForCompanyCount;
    await company.save({ validateModifiedOnly: true });

    order.qrCodesGenerated = true;
    order.qrGeneratedCount = totalQty;
    if (qrsToUse.length > 0) {
      order.startSerialNumber = qrsToUse[0].serialNumber;
      order.endSerialNumber = qrsToUse[qrsToUse.length - 1].serialNumber;
    }
    order.status = 'Received'; // Mark as Received since they already have the physical QRs
    order.history.push({
      status: 'Received',
      changedBy: req.user._id,
      role: req.user.role,
      comment: 'Order authorized and physical QRs mapped automatically.'
    });

    await order.save();
    
    // Create ProductCoupon entries if order has coupon data
    if (order.coupon && order.coupon.title) {
      try {
        const createdProducts = await Product.find({ orderId: order._id }).select('_id').lean();
        const couponDocs = createdProducts.map(p => ({
          title: order.coupon.title,
          code: order.coupon.code || '',
          description: order.coupon.description || '',
          websiteLink: order.coupon.websiteLink || '',
          expiryDate: order.coupon.expiryDate || null,
          discountType: order.coupon.discountType || 'percentage',
          discountValue: order.coupon.discountValue || null,
          mrp: order.coupon.mrp || null,
          productId: p._id,
          orderId: order._id,
          brandId: brandDoc ? brandDoc._id : null,
          companyId: brandDoc ? brandDoc.companyId : null,
        }));
        await ProductCoupon.insertMany(couponDocs);
      } catch (couponErr) {
        console.warn('Failed to create product coupons:', couponErr.message);
      }
    }

    // Send email notifications
    const recipients = await getNotificationRecipients(order);
    await sendOrderStatusEmail(recipients, {
      orderId: order.orderId,
      productName: order.productName,
      brand: order.brand,
      quantity: totalQty,
      status: order.status,
      changedBy: req.user.name || req.user.email
    }, `Order authorized by ${req.user.name || req.user.email}. Physical QRs mapped and order completed automatically.`);
    
    res.json(order);
  } catch (error) {
    console.error('Authorize order error:', error);
    res.status(500).json({ message: 'Server Error', error: error.message });
  }
});

// 5. PROCESS ORDER & GENERATE QRs (Super Admin)
router.put('/:id/process', protect, authorize('admin', 'superadmin'), async (req, res) => {
  try {
    const order = await Order.findById(req.params.id).populate('brandId').populate('company');

    if (!order) {
      return res.status(404).json({ message: 'Order not found' });
    }

    if (order.status !== 'Authorized') {
      return res.status(400).json({ message: 'Order must be authorized first' });
    }

    // Update status to processing
    order.status = 'Order Processing';
    order.history.push({
      status: 'Order Processing',
      changedBy: req.user._id,
      role: req.user.role,
      comment: 'Generating QR codes...'
    });

    await order.save();

    // GENERATE QR CODES
    const productsToCreate = [];
    const bonusQty = parseInt(req.body?.bonusQuantity) || 0;
    const required = order.quantity || 0;
    const totalQty = Math.max(required, bonusQty);
    const brandName = order.brand;
    
    // Fetch ProductTemplate and copy orderLinks
    const ProductTemplate = __nccwpck_require__(58846);
    let templateOrderLinks = [];
    let templateEducationContent = [];
    if (order.templateId) {
      const tpl = await ProductTemplate.findById(order.templateId).lean();
      if (tpl && tpl.orderLinks) templateOrderLinks = tpl.orderLinks;
      if (tpl && tpl.educationContent) templateEducationContent = tpl.educationContent;
    }
    
    // Track bonus in order
    order.bonusQuantity = bonusQty;
    
    // Find last sequence number for this brand
    const lastProduct = await Product.findOne({ brand: brandName }).sort({ sequence: -1 });
    let startSeq = lastProduct && lastProduct.sequence ? lastProduct.sequence + 1 : 1;

    // Try to resolve Brand record for this order if available
    const brandDoc = await Brand.findOne({ brandName: brandName });

    const BlankQr = __nccwpck_require__(50294);
    let qrsToUse = [];
    
    // Check if this is a company order
    let targetCompanyId = null;
    if (brandDoc && brandDoc.companyId) {
        targetCompanyId = brandDoc.companyId;
    } else if (order.company) {
        targetCompanyId = order.company._id || order.company;
    }

    if (targetCompanyId) {
        // Find unassigned physical QRs assigned to this company
        qrsToUse = await BlankQr.find({ 
            assignedToCompany: targetCompanyId,
            isAssigned: false,
            isBlocked: false
        })
        .sort({ serialNumber: 1 })
        .limit(totalQty);

        if (qrsToUse.length < totalQty) {
            return res.status(400).json({ 
                message: `Not enough physical Blank QRs available for this company. Requested: ${totalQty}, Available: ${qrsToUse.length}. Please assign more QRs to the company first.` 
            });
        }
    }

    for (let i = 0; i < totalQty; i++) {
      const currentSeq = startSeq + i;
      
      let qrCode = '';
      if (qrsToUse.length > 0) {
          // Use physical QR
          qrCode = qrsToUse[i].qrCode;
      } else {
          // Fallback to generating digital QR
          const seqString = currentSeq.toString().padStart(6, '0');
          const uniqueSuffix = Math.random().toString(36).substring(2, 6).toUpperCase();
          qrCode = `${brandName}-${seqString}-${order.orderId}-${uniqueSuffix}`;
      }
      
      productsToCreate.push({
        qrCode,
        productName: order.productName,
        skuNumber: order.skuNumber,
        brand: brandName,
        brandId: brandDoc ? brandDoc._id : null,
        batchNo: order.batchNo,
        manufactureDate: order.manufactureDate,
        expiryDate: order.expiryDate,
        productImage: order.productImage,
        mfdOn: (order.mfdOn && order.mfdOn.month && order.mfdOn.year) ? order.mfdOn : undefined,
        bestBefore: (order.bestBefore && order.bestBefore.value) ? order.bestBefore : undefined,
        calculatedExpiryDate: order.calculatedExpiryDate,
        dynamicFields: order.dynamicFields,
        variants: order.variants,
        warranty: (order.warranty && (order.warranty.duration || order.warranty.warrantyType)) ? order.warranty : undefined,
        supplyChain: order.supplyChain || undefined,
        orderLinks: (order.orderLinks && order.orderLinks.length > 0) ? order.orderLinks : templateOrderLinks,
        educationContent: templateEducationContent,
        description: order.description,
        productInfo: order.productInfo,
        quantity: 1,
        sequence: currentSeq,
        orderId: order._id,
        isActive: false, // QRs are inactive until authorizer receives
        createdBy: req.user._id
      });
    }
    
    const insertedProducts = await Product.insertMany(productsToCreate);
    
    if (qrsToUse.length > 0) {
        // Map Blank QRs to the created products
        const bulkOps = insertedProducts.map((prod, index) => ({
            updateOne: {
                filter: { _id: qrsToUse[index]._id },
                update: { $set: { isAssigned: true, assignedToProduct: prod._id } }
            }
        }));
        await BlankQr.bulkWrite(bulkOps);
    }
    
    // Record bonus transaction if needed (admin grant)
    if (bonusQty > 0 && order.company) {
      const company = await Company.findById(order.company._id || order.company);
      if (company) {
        // Technically this doesn't deduct from balance, but it's a grant record
        // We track it as admin_grant
        await CreditTransaction.create({
          companyId: company._id,
          type: 'admin_grant',
          amount: bonusQty,
          balanceAfter: company.qrCredits, // Balance remains same as it was a free grant for this specific batch
          performedBy: req.user._id,
          orderId: order._id,
          note: `Bonus QR grant by ${req.user.role}: ${bonusQty} for Order ${order.orderId}`
        });
      }
    }

    // Update order
    order.qrCodesGenerated = true;
    order.qrGeneratedCount = totalQty;
    if (qrsToUse.length > 0) {
      order.startSerialNumber = qrsToUse[0].serialNumber;
      order.endSerialNumber = qrsToUse[qrsToUse.length - 1].serialNumber;
    }
    await order.save();

    // Create ProductCoupon entries if order has coupon data
    if (order.coupon && order.coupon.title) {
      try {
        const createdProducts = await Product.find({ orderId: order._id }).select('_id').lean();
        const couponDocs = createdProducts.map(p => ({
          title: order.coupon.title,
          code: order.coupon.code || '',
          description: order.coupon.description || '',
          websiteLink: order.coupon.websiteLink || '',
          expiryDate: order.coupon.expiryDate || null,
          discountType: order.coupon.discountType || 'percentage',
          discountValue: order.coupon.discountValue || null,
          mrp: order.coupon.mrp || null,
          productId: p._id,
          orderId: order._id,
          brandId: brandDoc ? brandDoc._id : null,
          companyId: brandDoc ? brandDoc.companyId : null,
        }));
        await ProductCoupon.insertMany(couponDocs);
        console.log(`Created ${couponDocs.length} ProductCoupon entries for order ${order.orderId}`);
      } catch (couponErr) {
        console.warn('Failed to create product coupons:', couponErr.message);
      }
    }

    // Send email notifications
    const recipients = await getNotificationRecipients(order);
    await sendOrderStatusEmail(recipients, {
      orderId: order.orderId,
      productName: order.productName,
      brand: order.brand,
      quantity: totalQty, // Use totalQty in email
      status: order.status,
      changedBy: req.user.name || req.user.email
    }, `${totalQty} QR codes generated successfully (including ${bonusQty} bonus).`);
    
    res.json({ 
      message: 'QR codes generated successfully', 
      order,
      qrCount: totalQty,
      bonusAdded: bonusQty
    });
  } catch (error) {
    console.error('Process order error:', error);
    res.status(500).json({ message: 'Server Error', error: error.message });
  }
});

